import re,sys,os,glob
def parse(p):
    txt=open(p,encoding='utf-8',errors='replace').read()
    # split into sections
    secs={}
    cur=None
    for line in txt.splitlines():
        s=line.strip()
        m=re.match(r'^\[([A-Za-z_]+)\]',s)
        if m:
            cur=m.group(1).upper(); secs.setdefault(cur,[]); continue
        if cur is None: continue
        if not s or s.startswith(';'): continue
        secs[cur].append(s)
    def n(k): return len(secs.get(k,[]))
    vt={}
    for row in secs.get('VALVES',[]):
        f=row.split()
        if len(f)>=5:
            t=f[4].upper()
            vt[t]=vt.get(t,0)+1
    pumpinfo=[]
    for row in secs.get('PUMPS',[]):
        f=row.split(';')[0].split()
        pumpinfo.append(' '.join(f))
    opts={}
    for row in secs.get('OPTIONS',[]):
        f=row.split(';')[0].split()
        if len(f)>=2: opts[f[0].upper()]=' '.join(f[1:])
    times={}
    for row in secs.get('TIMES',[]):
        f=row.split(';')[0].split()
        if len(f)>=2: times[' '.join(f[:-1]).upper()]=f[-1]
    print('='*70)
    print(os.path.basename(p))
    print(f"  JUNCTIONS={n('JUNCTIONS')} RESERVOIRS={n('RESERVOIRS')} TANKS={n('TANKS')} PIPES={n('PIPES')} PUMPS={n('PUMPS')} VALVES={n('VALVES')}")
    print(f"  VALVE TYPES: {vt if vt else 'none'}")
    print(f"  EMITTERS={n('EMITTERS')} CONTROLS={n('CONTROLS')} RULES={n('RULES')} PATTERNS_rows={n('PATTERNS')} CURVES_rows={n('CURVES')} DEMANDS_rows={n('DEMANDS')}")
    print(f"  UNITS={opts.get('UNITS')} HEADLOSS={opts.get('HEADLOSS')} DEMAND={[k+'='+v for k,v in opts.items() if 'DEMAND' in k or 'MINIMUM' in k or 'REQUIRED' in k or 'PRESSURE' in k]}")
    print(f"  TIMES: dur={times.get('DURATION')} hyd={times.get('HYDRAULIC TIMESTEP')} pat={times.get('PATTERN TIMESTEP')} rep={times.get('REPORT TIMESTEP')}")
    print("  PUMPS:")
    for x in pumpinfo[:14]: print("    ",x)
    if len(pumpinfo)>14: print(f"     ... (+{len(pumpinfo)-14} more)")
    if secs.get('VALVES'):
        print("  VALVE ROWS (first 12):")
        for x in secs['VALVES'][:12]: print("    ",x.split(';')[0])
for p in sys.argv[1:]:
    try: parse(p)
    except Exception as e: print('ERR',p,e)
