import json
d=json.load(open('results/phase5/g9_g10_full.json',encoding='utf-8'))
for k,v in d['cases'].items():
    print('=====',k,'geom_passes',v['geometric_storage_passes'])
    print(' precision_floor', json.dumps(v['output_precision_floor']))
    gs=v['geometric_storage']
    print(' keys', list(gs.keys()))
    for t,tv in gs['tanks'].items():
        print(' ',t, {kk:tv[kk] for kk in tv if 'error' in kk or 'dV' in kk})
    for kk in gs:
        if kk not in ('tanks','gal_per_m3','interval_h'): print('  ',kk,gs[kk])
