import json,io
p=r'D:\Thesis\docs\ai-knowledge\session-backup\claude-code-transcripts--D--Thesis\efb840bd-2980-4341-8a7c-52696bec3900.jsonl'
rows=[json.loads(l) for l in io.open(p,encoding='utf-8') if l.strip()]
print('lines',len(rows))
ts=[r.get('timestamp') for r in rows if r.get('timestamp')]
print('first',ts[0] if ts else None,'last',ts[-1] if ts else None)
print('versions',sorted({r.get('version') for r in rows if r.get('version')}))
print('cwds',sorted({r.get('cwd') for r in rows if r.get('cwd')}))
ut=[]
for r in rows:
    if r.get('type')=='user':
        m=r.get('message',{})
        c=m.get('content')
        if isinstance(c,str): ut.append(c[:220])
        elif isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='text': ut.append(b['text'][:220])
print(json.dumps(ut[:4],ensure_ascii=False,indent=1))
